#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

KEY_FILE="service-account.json"

banner "health-cloud: Google Health subscriber credentials"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Identify the Google Cloud project"
say "Every later stage needs the project number. It is not stored in this"
say "script: it comes from the environment, or from $ENV_FILE, or from you."
note "Find it on the console dashboard, or with:"
note "  gcloud projects describe <project-id> --format='value(projectNumber)'"
if [[ -n "${GCP_PROJECT_NUMBER:-}" ]]; then
  PROJECT_NUMBER="$GCP_PROJECT_NUMBER"
  note "using GCP_PROJECT_NUMBER from the environment"
else
  ask GCP_PROJECT_NUMBER "Google Cloud project number:"
  PROJECT_NUMBER="$GCP_PROJECT_NUMBER"
fi
if [[ -z "$PROJECT_NUMBER" ]]; then
  warn "no project number given; cannot continue"
  exit 1
fi
write_env GCP_PROJECT_NUMBER "$PROJECT_NUMBER"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Create the service account"
say "Subscriber management is a project-level API. It is authorised by a"
say "service account, not by the user tokens from the sign-in flow."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts/create?project=${PROJECT_NUMBER}"
step "Service account name: health-cloud-subscriber"
step "Click 'Create and continue'."
step "Skip the optional role and access steps, then click 'Done'."
step "Back on the list, copy the new account's email address."
note "It looks like health-cloud-subscriber@<project-id>.iam.gserviceaccount.com"
ask SERVICE_ACCOUNT_EMAIL "Paste the service account email:"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Grant it permission to manage subscribers"
say "Without this role, creating a subscriber fails with PERMISSION_DENIED."
open_url "https://console.cloud.google.com/iam-admin/iam?project=${PROJECT_NUMBER}"
step "Click 'Grant access' at the top."
step "New principals: ${SERVICE_ACCOUNT_EMAIL:-<the email you just copied>}"
step "Role: search for 'Google Health API Admin' and select it."
step "Click 'Save'."
note "'Google Health API Editor' may also suffice. Stage 6 will tell you"
note "whether the role you picked actually works."
pause "Press Enter once the role is saved."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Download a JSON key"
say "This key is a long-lived secret. It stays out of git."
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts?project=${PROJECT_NUMBER}"
step "Click the health-cloud-subscriber account."
step "Open the 'Keys' tab → 'Add key' → 'Create new key' → JSON → Create."
step "Your browser downloads a .json file."
say ""
say "Now move that file into this repo as ${KEY_FILE}."
note "e.g. mv ~/Downloads/<project>-*.json $(pwd)/${KEY_FILE}"
pause "Press Enter once the file is in place."

if [[ -f "$KEY_FILE" ]]; then
  printf '  %s✓ found%s %s\n' "$GREEN" "$RESET" "$KEY_FILE"
else
  warn "$KEY_FILE not found in $(pwd) - stage 6 will fail until it is there"
  SKIPPED+=("move the downloaded key to $(pwd)/${KEY_FILE}")
fi

# Keep the key out of git, idempotently.
if ! grep -qxF "$KEY_FILE" .gitignore 2>/dev/null; then
  printf '\n# Service account key for subscriber management\n%s\n' "$KEY_FILE" >> .gitignore
  printf '  %s✓ added%s %s to .gitignore\n' "$GREEN" "$RESET" "$KEY_FILE"
else
  note "$KEY_FILE is already gitignored"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Generate the webhook endpoint secret"
say "Google sends this string verbatim in the Authorization header of every"
say "notification. The receiver compares it in constant time, and rejects the"
say "request when it does not match."
if command -v openssl >/dev/null 2>&1; then
  GENERATED_SECRET="$(openssl rand -hex 32)"
  note "generated 32 random bytes"
else
  GENERATED_SECRET="$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')"
  note "generated 32 random bytes (openssl not found, used /dev/urandom)"
fi
write_env WEBHOOK_AUTH_SECRET "$GENERATED_SECRET"
note "the value is not printed; it is written straight to $ENV_FILE"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Record the remaining settings"
say "These identify the project and the subscriber registration."
write_env GOOGLE_APPLICATION_CREDENTIALS "$KEY_FILE"
say ""
say "The subscriber id names this registration inside the project."
note "Lowercase letters, digits and hyphens; 4-36 characters."
ask SUBSCRIBER_ID "Subscriber id [health-cloud-local]:"
SUBSCRIBER_ID="${SUBSCRIBER_ID:-health-cloud-local}"
write_env SUBSCRIBER_ID "$SUBSCRIBER_ID"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Check the credentials actually work"
say "This mints a token from the key and lists the project's subscribers."
say "It proves two separate things: the key is valid, and the role is right."
say ""

if [[ ! -f "$KEY_FILE" ]]; then
  warn "no $KEY_FILE, so nothing to check"
elif ! command -v uv >/dev/null 2>&1; then
  warn "uv not found; re-run this stage later"
  SKIPPED+=("validate credentials: uv run python scripts/check_service_account.py")
else
  if uv run python scripts/check_service_account.py; then
    printf '  %s✓ credentials work%s\n' "$GREEN" "$RESET"
  else
    warn "the check failed - read the message above"
    SKIPPED+=("fix the service account, then re-run: uv run python scripts/check_service_account.py")
  fi
fi

finish
